"""Semantic version parsing, comparison, and range matching.

Versions follow Semantic Versioning 2.0.0: ``MAJOR.MINOR.PATCH``, then an
optional pre-release (``-`` followed by dot-separated identifiers) and an
optional build (``+`` followed by dot-separated identifiers). Identifiers
are non-empty and made of ASCII letters, digits, and hyphens. Numeric parts
(MAJOR, MINOR, PATCH, and all-digit pre-release identifiers) must not have
leading zeros. Anything else is invalid and raises ``ValueError``.

Precedence (``compare``) follows the SemVer 2.0.0 rules: compare MAJOR,
MINOR, and PATCH numerically; a version with a pre-release is lower than
the same version without one; pre-release identifiers are compared left to
right, all-digit ones numerically and the rest in ASCII order, with
all-digit identifiers lower than the rest, and a shorter list lower when
all its identifiers equal the start of a longer one. Build metadata is
ignored.

Ranges (``satisfies``) are one or more comparator sets joined by ``||``; a
version satisfies the range if it satisfies any set. A set is one or more
comparators separated by whitespace, all of which must hold. A comparator
is a full version optionally prefixed by an operator:

- ``=`` (or no operator), ``>``, ``>=``, ``<``, ``<=``: by precedence.
- ``^X.Y.Z``: at least ``X.Y.Z`` and below the next version that changes
  the leftmost non-zero part, i.e. ``^1.2.3`` is ``>=1.2.3 <2.0.0``,
  ``^0.2.3`` is ``>=0.2.3 <0.3.0``, and ``^0.0.3`` is ``>=0.0.3 <0.0.4``.
- ``~X.Y.Z``: at least ``X.Y.Z`` and below ``X.(Y+1).0``.

A version with a pre-release satisfies a set only if some comparator in
that set has a pre-release on the same MAJOR.MINOR.PATCH (so
``1.2.3-beta.2`` satisfies ``>=1.2.3-beta.1`` but not ``>=1.0.0``).
Invalid ranges raise ``ValueError``.
"""

from __future__ import annotations

import re
from dataclasses import dataclass


# All character classes are spelled out in ASCII terms; using ``\d`` or ``\w``
# would also accept non-ASCII characters.
_IDENTIFIER = r"[0-9A-Za-z-]+"
_IDENTIFIER_LIST = rf"{_IDENTIFIER}(?:\.{_IDENTIFIER})*"
_VERSION_RE = re.compile(
    rf"(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)"
    rf"(?:-({_IDENTIFIER_LIST}))?"
    rf"(?:\+({_IDENTIFIER_LIST}))?"
)
_COMPARATOR_RE = re.compile(r"(>=|<=|>|<|=|\^|~)?(.+)")


@dataclass(frozen=True)
class Version:
    major: int
    minor: int
    patch: int
    prerelease: tuple[str, ...] = ()
    build: tuple[str, ...] = ()

    def __str__(self) -> str:
        """The version in canonical form, e.g. ``1.2.3-rc.1+build.5``."""
        text = f"{self.major}.{self.minor}.{self.patch}"
        if self.prerelease:
            text += "-" + ".".join(self.prerelease)
        if self.build:
            text += "+" + ".".join(self.build)
        return text


def parse(text: str) -> Version:
    """Parse a version string."""
    if not isinstance(text, str):
        raise ValueError(f"invalid version: {text!r}")

    match = _VERSION_RE.fullmatch(text)
    if match is None:
        raise ValueError(f"invalid version: {text!r}")

    major, minor, patch, prerelease, build = match.groups()
    prerelease_parts = tuple(prerelease.split(".")) if prerelease else ()
    build_parts = tuple(build.split(".")) if build else ()

    for identifier in prerelease_parts:
        if _is_numeric(identifier) and len(identifier) > 1 and identifier[0] == "0":
            raise ValueError(f"invalid version: {text!r}")

    return Version(
        int(major),
        int(minor),
        int(patch),
        prerelease_parts,
        build_parts,
    )


def compare(a: str | Version, b: str | Version) -> int:
    """Return -1, 0, or 1 as ``a`` has lower, equal, or higher precedence."""
    left = _as_version(a)
    right = _as_version(b)

    for left_part, right_part in zip(
        (left.major, left.minor, left.patch),
        (right.major, right.minor, right.patch),
    ):
        result = _compare_numeric(left_part, right_part)
        if result:
            return result

    if not left.prerelease and not right.prerelease:
        return 0
    if not left.prerelease:
        return 1
    if not right.prerelease:
        return -1

    for left_part, right_part in zip(left.prerelease, right.prerelease):
        left_numeric = _is_numeric(left_part)
        right_numeric = _is_numeric(right_part)
        if left_numeric and right_numeric:
            result = _compare_numeric(int(left_part), int(right_part))
        elif left_numeric:
            result = -1
        elif right_numeric:
            result = 1
        elif left_part < right_part:
            result = -1
        elif left_part > right_part:
            result = 1
        else:
            result = 0
        if result:
            return result

    return _compare_numeric(len(left.prerelease), len(right.prerelease))


def satisfies(version: str | Version, range_: str) -> bool:
    """Whether ``version`` is in ``range_``."""
    candidate = _as_version(version)
    if not isinstance(range_, str):
        raise ValueError(f"invalid range: {range_!r}")

    sets = range_.split("||")
    if not sets:
        raise ValueError(f"invalid range: {range_!r}")

    parsed_sets = []
    for comparator_set in sets:
        if not comparator_set.strip():
            raise ValueError(f"invalid range: {range_!r}")

        comparators = []
        for token in comparator_set.split():
            match = _COMPARATOR_RE.fullmatch(token)
            if match is None:
                raise ValueError(f"invalid comparator: {token!r}")
            operator, version_text = match.groups()
            comparator_version = parse(version_text)
            comparators.append((operator or "=", comparator_version))
        parsed_sets.append(comparators)

    for comparators in parsed_sets:
        if all(
            _matches(candidate, operator, comparator_version)
            for operator, comparator_version in comparators
        ) and (
            not candidate.prerelease
            or any(
                comparator_version.prerelease
                and (
                    comparator_version.major,
                    comparator_version.minor,
                    comparator_version.patch,
                )
                == (candidate.major, candidate.minor, candidate.patch)
                for _, comparator_version in comparators
            )
        ):
            return True

    return False


def _as_version(value: str | Version) -> Version:
    if isinstance(value, Version):
        return value
    return parse(value)


def _is_numeric(identifier: str) -> bool:
    return bool(identifier) and identifier.isascii() and identifier.isdigit()


def _compare_numeric(a: int, b: int) -> int:
    if a < b:
        return -1
    if a > b:
        return 1
    return 0


def _matches(candidate: Version, operator: str, version: Version) -> bool:
    result = compare(candidate, version)

    if operator == "=":
        return result == 0
    if operator == ">":
        return result > 0
    if operator == ">=":
        return result >= 0
    if operator == "<":
        return result < 0
    if operator == "<=":
        return result <= 0

    if operator == "^":
        if version.major > 0:
            upper = Version(version.major + 1, 0, 0)
        elif version.minor > 0:
            upper = Version(0, version.minor + 1, 0)
        else:
            upper = Version(0, 0, version.patch + 1)
        return result >= 0 and compare(candidate, upper) < 0

    if operator == "~":
        upper = Version(version.major, version.minor + 1, 0)
        return result >= 0 and compare(candidate, upper) < 0

    # Unreachable: the comparator regex only recognises the operators above.
    raise ValueError(f"invalid operator: {operator!r}")

