        for _ in range(random.randint(1, 3)):
            build.append(random.choice(NUMERIC + ALPHA))
        text += "+" + ".".join(build)
    return text, tuple(core), tuple(prerelease)


def ref_key(item):
    text, core, prerelease = item
    if not prerelease:
        pre_key = (1,)
    else:
        pre_key = (
            0,
            tuple((0, int(part), "") if part.isdigit() else (1, 0, part)
                  for part in prerelease),
        )
    return core + (pre_key,)


def sign(value):
    return (value > 0) - (value < 0)


